export type ParsedBorrowPerfectInstruction<
  TProgram extends string = typeof LEND_DEX_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The protocol calling the operation (must match position.protocol) */
    signer: TAccountMetas[0];
    /** DEX pool state */
    dex: TAccountMetas[1];
    user: TAccountMetas[2];
    /** The user's DexPosition (tracks shares and limits) */
    position: TAccountMetas[3];
    userToken0Account: TAccountMetas[4];
    userToken1Account: TAccountMetas[5];
    token0: TAccountMetas[6];
    token1: TAccountMetas[7];
    token0Reserve: TAccountMetas[8];
    token1Reserve: TAccountMetas[9];
    token0RateModel: TAccountMetas[10];
    token1RateModel: TAccountMetas[11];
    /** Liquidity vault token account for tokens */
    token0Vault: TAccountMetas[12];
    token1Vault: TAccountMetas[13];
    /** DEX's supply position for tokens on liquidity */
    dexSupplyPositionToken0?: TAccountMetas[14] | undefined;
    dexSupplyPositionToken1?: TAccountMetas[15] | undefined;
    /** DEX's borrow position for tokens on liquidity */
    dexBorrowPositionToken0?: TAccountMetas[16] | undefined;
    dexBorrowPositionToken1?: TAccountMetas[17] | undefined;
    liquidity: TAccountMetas[18];
    liquidityProgram: TAccountMetas[19];
    oracleProgram: TAccountMetas[20];
    token0Program: TAccountMetas[21];
    token1Program: TAccountMetas[22];
    recipient?: TAccountMetas[23] | undefined;
    recipientToken0Account?: TAccountMetas[24] | undefined;
    recipientToken1Account?: TAccountMetas[25] | undefined;
  };
  data: BorrowPerfectInstructionData;
};

export function parseBorrowPerfectInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBorrowPerfectInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 26) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 26,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === LEND_DEX_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      dex: getNextAccount(),
      user: getNextAccount(),
      position: getNextAccount(),
      userToken0Account: getNextAccount(),
      userToken1Account: getNextAccount(),
      token0: getNextAccount(),
      token1: getNextAccount(),
      token0Reserve: getNextAccount(),
      token1Reserve: getNextAccount(),
      token0RateModel: getNextAccount(),
      token1RateModel: getNextAccount(),
      token0Vault: getNextAccount(),
      token1Vault: getNextAccount(),
      dexSupplyPositionToken0: getNextOptionalAccount(),
      dexSupplyPositionToken1: getNextOptionalAccount(),
      dexBorrowPositionToken0: getNextOptionalAccount(),
      dexBorrowPositionToken1: getNextOptionalAccount(),
      liquidity: getNextAccount(),
      liquidityProgram: getNextAccount(),
      oracleProgram: getNextAccount(),
      token0Program: getNextAccount(),
      token1Program: getNextAccount(),
      recipient: getNextOptionalAccount(),
      recipientToken0Account: getNextOptionalAccount(),
      recipientToken1Account: getNextOptionalAccount(),
    },
    data: getBorrowPerfectInstructionDataDecoder().decode(instruction.data),
  };
}
